open Raster2
let ok=function Ok x->x|Error _->failwith"texture error"
let make frame=let surface=ok(Surface.create~width:3~height:5~pitch:16())in Bytes.fill(Surface.bytes surface)0(Bytes.length(Surface.bytes surface))'\x7f';for y=0 to 4 do for x=0 to 2 do ignore(Surface.set_rgba surface~x~y(Int32.of_int((((frame+x*40)land 255)lsl 24)lor(y*40 lsl 16)lor 0x00ff)))done done;ok(Texture.create~color_space:Texture.Linear~hard_capacity:1024 surface)
let render frame=let texture=make frame in assert(Texture.levels texture=4&&Texture.storage_bytes texture=96);let values=[Texture.sample texture~address_u:Clamp~address_v:Clamp~filter:Nearest~u:(-1.)~v:2.~lod:0.;Texture.sample texture~address_u:Repeat~address_v:Mirror~filter:Bilinear~u:1.2~v:(-0.3)~lod:1.;Texture.sample texture~address_u:Mirror~address_v:Repeat~filter:Trilinear~u:2.4~v:1.7~lod:1.5]in Marshal.to_bytes(List.map ok values)[]
let ()=List.iter(fun frame->let expected=render frame in let workers=Array.init 4(fun _->Domain.spawn(fun()->render frame))in Array.iter(fun worker->assert(Domain.join worker=expected))workers)[1;600];let source=ok(Surface.create~width:1~height:1())in(match Texture.create~color_space:Srgb~hard_capacity:3 source with Error Texture.Capacity_exceeded->()|_->failwith"capacity");let srgb=ok(Texture.create~color_space:Srgb~hard_capacity:4 source)in(match Texture.sample srgb~address_u:Clamp~address_v:Clamp~filter:Nearest~u:nan~v:0.~lod:0. with Error Texture.Invalid_coordinate->()|_->failwith"nan");print_endline"Raster2 deterministic texture mip sampling passed"
